import{_ as r,o as t,c as o,a5 as a}from"./chunks/framework.CXroN2RO.js";const d="/study/images/graphics/vertex-and-index-input.svg",g=JSON.parse('{"title":"頂点バッファとインデックスバッファから三角形を組み立てる","description":"","frontmatter":{"title":"頂点バッファとインデックスバッファから三角形を組み立てる","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"D3D12がインデックスから頂点を選び、ストライドと属性のオフセットで入力を取り出す手順を扱う。glTFの読み取り、描画範囲の検査、バッファの寿命までつなげる。","aliases":["頂点バッファ","vertex buffer","インデックスバッファ","index buffer","input assembler","input layout","stride","DrawIndexedInstanced","BaseVertexLocation"],"verification":"KhronosのglTF 2.0仕様とMicrosoftのD3D12 API資料に照合（2026-11-06）"}},"headers":[],"relativePath":"graphics/mesh/vertex-and-index-input.md","filePath":"graphics/mesh/vertex-and-index-input.md"}'),s={name:"graphics/mesh/vertex-and-index-input.md"};function n(i,e,c,l,h,f){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="頂点バッファとインデックスバッファから三角形を組み立てる" tabindex="-1">頂点バッファとインデックスバッファから三角形を組み立てる <a class="header-anchor" href="#頂点バッファとインデックスバッファから三角形を組み立てる" aria-label="Permalink to &quot;頂点バッファとインデックスバッファから三角形を組み立てる&quot;">​</a></h1><p><strong>頂点バッファ</strong>には位置や法線などの属性が並び、<strong>インデックスバッファ</strong>には、それらを参照する頂点番号が並びます。三角形リストでは番号を3個ずつ使うので、<code>[2, 0, 1]</code>は頂点2、0、1の順で一つの三角形を作ります。隣り合う三角形が位置・法線・UVなどを共有できる場合は、同じ頂点番号を何度でも使えます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">Khronosのメッシュプリミティブの仕様</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12graphicscommandlist-drawindexedinstanced" target="_blank" rel="noreferrer">Microsoftのインデックス付き描画</a></p><figure class="study-figure"><img src="'+d+'" alt="16ビットのインデックスが2、0、1の順に並ぶ。先頭の値2が選ぶ頂点は、24バイト間隔で並ぶ頂点バッファの48バイト目から始まる。位置は頂点先頭の48バイト目、法線はそこから12バイト後の60バイト目にある。" width="760" height="410" loading="lazy"><figcaption>インデックスの読み取り位置と、インデックスの値で選ぶ頂点の位置を区別します。<a href="/study/images/graphics/vertex-and-index-input.svg" target="_blank" rel="noopener noreferrer">頂点入力の図を拡大</a></figcaption></figure><h2 id="頂点番号から属性の位置を求める" tabindex="-1">頂点番号から属性の位置を求める <a class="header-anchor" href="#頂点番号から属性の位置を求める" aria-label="Permalink to &quot;頂点番号から属性の位置を求める&quot;">​</a></h2><p>例えば、位置と法線をそれぞれ3個の32ビット浮動小数点数で持つ場合、各属性は12バイトです。頂点ごとに位置と法線をまとめて並べると、次の頂点までの間隔である<strong>ストライド</strong>は24バイトになります。属性の<strong>オフセット</strong>は、一つの頂点の先頭から測ります。D3D12では頂点バッファビューが先頭アドレス、バイト数、ストライドを持ち、パイプラインの入力レイアウトが各属性の形式、オフセット、参照する入力スロットを指定します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ns-d3d12-d3d12_vertex_buffer_view" target="_blank" rel="noreferrer">Microsoftの頂点バッファビュー</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ns-d3d12-d3d12_input_element_desc" target="_blank" rel="noreferrer">Microsoftの入力要素の記述</a></p><table tabindex="0"><thead><tr><th>属性</th><th>形式</th><th>頂点内のオフセット</th><th>頂点2を読む場合のバッファ内位置</th></tr></thead><tbody><tr><td><code>POSITION</code></td><td><code>DXGI_FORMAT_R32G32B32_FLOAT</code></td><td>0バイト</td><td><code>2 × 24 + 0 = 48</code>バイト</td></tr><tr><td><code>NORMAL</code></td><td><code>DXGI_FORMAT_R32G32B32_FLOAT</code></td><td>12バイト</td><td><code>2 × 24 + 12 = 60</code>バイト</td></tr></tbody></table><p>この例では二つの属性を同じ入力スロットに設定し、HLSLの入力ではそれぞれ<code>float3 position : POSITION</code>、<code>float3 normal : NORMAL</code>として受け取れます。入力レイアウトのセマンティック名と番号を頂点シェーダーの入力に合わせます。頂点シェーダーは取得した位置から、ラスタライザーへ渡す<code>SV_Position</code>を計算します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3dhlsl/dx-graphics-hlsl-semantics" target="_blank" rel="noreferrer">MicrosoftのHLSLセマンティック</a> · <a href="/study/graphics/pipeline/vertex-shader.html">頂点シェーダーの役割</a></p><h2 id="インデックス列の開始位置と、頂点番号の加算値" tabindex="-1">インデックス列の開始位置と、頂点番号の加算値 <a class="header-anchor" href="#インデックス列の開始位置と、頂点番号の加算値" aria-label="Permalink to &quot;インデックス列の開始位置と、頂点番号の加算値&quot;">​</a></h2><p><code>IASetIndexBuffer</code>には、インデックスバッファの先頭アドレス、バイト数、形式を持つビューを渡します。D3D12では16ビットの<code>DXGI_FORMAT_R16_UINT</code>、または32ビットの<code>DXGI_FORMAT_R32_UINT</code>を使います。glTFの<code>indices</code>が8ビット符号なし整数の場合は、例えば読み込み時に16ビットへ広げてバッファに詰めます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ns-d3d12-d3d12_index_buffer_view" target="_blank" rel="noreferrer">Microsoftのインデックスバッファビュー</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddxgi/hardware-support-for-direct3d-12-0-formats" target="_blank" rel="noreferrer">Microsoftの形式サポート表</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">Khronosのインデックスの仕様</a></p><p><code>DrawIndexedInstanced(3, 1, 0, 0, 0)</code>では、1インスタンスを描き、ビューの先頭から3個のインデックスを読みます。複数のメッシュを一つのバッファにまとめる場合は、<code>StartIndexLocation</code>と<code>BaseVertexLocation</code>を使い分けます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12graphicscommandlist-drawindexedinstanced" target="_blank" rel="noreferrer">Microsoftの<code>DrawIndexedInstanced</code></a></p><table tabindex="0"><thead><tr><th>引数</th><th>何をずらすか</th><th>例</th></tr></thead><tbody><tr><td><code>StartIndexLocation</code></td><td>インデックスビュー内で、読み始める要素番号</td><td><code>6</code>なら7個目から読む。16ビット形式ならビュー先頭から12バイト目。</td></tr><tr><td><code>BaseVertexLocation</code></td><td>読み取った各インデックスに足す符号付きの値</td><td><code>100</code>なら<code>[2, 0, 1]</code>を<code>[102, 100, 101]</code>として頂点を読む。</td></tr></tbody></table><p>ローダーでは、開始位置と個数がインデックスビューに収まることを先に確かめます。次に、読み取った値に<code>BaseVertexLocation</code>を加えた結果が各頂点ストリームの範囲に収まるかを、符号と桁あふれに気をつけて確認します。glTFファイルの読み込み時にも、そのプリミティブの全属性で要素数が一致し、各インデックスが要素数より小さいことを確かめます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">Khronosのメッシュプリミティブの制約</a> · <a href="/study/graphics/mesh/gltf-mesh-buffers.html">glTFのバッファとアクセサー</a> · <a href="/study/data/binary-file-validation.html">バイナリの範囲検査</a></p><h2 id="同じ位置でも頂点が分かれる場合" tabindex="-1">同じ位置でも頂点が分かれる場合 <a class="header-anchor" href="#同じ位置でも頂点が分かれる場合" aria-label="Permalink to &quot;同じ位置でも頂点が分かれる場合&quot;">​</a></h2><p>一つのインデックスは、その頂点の位置、法線、UVなどを一緒に選びます。例えば立方体の角を二つの面が共有していても、面ごとに異なる法線を持つ場合は、位置が同じで法線が違う頂点を用意します。UVの継ぎ目も、同じ位置に異なるUVを持たせるために頂点を分ける例です。頂点をまとめる処理では、描画に使う属性の組み合わせを見て判断します。<a href="https://docs.blender.org/manual/en/5.3/addons/scene_gltf2.html#meshes" target="_blank" rel="noreferrer">BlenderのglTF書き出し仕様</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#meshes" target="_blank" rel="noreferrer">Khronosの頂点属性の仕様</a></p><h2 id="gltfのバイト列を描画に渡す" tabindex="-1">glTFのバイト列を描画に渡す <a class="header-anchor" href="#gltfのバイト列を描画に渡す" aria-label="Permalink to &quot;glTFのバイト列を描画に渡す&quot;">​</a></h2><ol><li><code>bufferView</code>とアクセサーから属性の配置を求めます。位置と法線が24バイト間隔で交互に入っていれば、先頭とストライドをビューに、属性ごとの形式とオフセットを入力レイアウトに指定できます。入力形式が描画側の配置と異なる場合は、要素を変換して詰め直します。<a href="/study/graphics/mesh/gltf-mesh-buffers.html">glTFのバッファとアクセサー</a></li><li>頂点とインデックスのデータをGPUが読めるバッファに置きます。例えば<code>UPLOAD</code>ヒープから<code>DEFAULT</code>ヒープへコピーする場合は、コピー後に頂点バッファを<code>VERTEX_AND_CONSTANT_BUFFER</code>、インデックスバッファを<code>INDEX_BUFFER</code>の用途で読めるようにします。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/uploading-resources" target="_blank" rel="noreferrer">Microsoftのリソース転送</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ne-d3d12-d3d12_resource_states" target="_blank" rel="noreferrer">Microsoftのリソース状態</a></li><li>ビューを<code>IASetVertexBuffers</code>と<code>IASetIndexBuffer</code>で設定し、三角形リストを選びます。コピー元の領域を再利用できるのはコピーが完了した後です。描画が参照する頂点・インデックスの領域は、描画の完了まで保持します。それぞれのキューでフェンスを使って完了を追います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/fence-based-resource-management" target="_blank" rel="noreferrer">Microsoftのフェンスによるメモリ再利用</a> · <a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースの寿命</a></li></ol><p>実践では、小さなGLBから頂点とインデックスを取得し、D3D12のWARPで三角形を描画します。描画先を読み戻して、インデックス付き描画の結果を確かめられます。<a href="/study/practice/graphics/glb-mesh-observation.html">C++でGLBから三角形を描く</a></p>',17)])])}const m=r(s,[["render",n]]);export{g as __pageData,m as default};
